using FixFinder.Core.LocalFixes;
using FixFinder.Core.Logic;

namespace FixFinder.Tests;

/// <summary>
/// A search in each language whose set of places visited is asked and never given anything - counting the places reached on a
/// graph whose edges come back round, or walking links until it comes back to a place - with the change that adds each place
/// where the search goes on from it; the same searches adding them, and searches near the mistake but not it, which are left
/// alone. Each row is what the check gave for the program when these were written.
/// </summary>
public class VisitedNeverAddedTests : IDisposable
{
    private readonly TempFolder _temp = new();

    public void Dispose()
    {
        _temp.Dispose();
        GC.SuppressFinalize(this);
    }

    private SourceFile Program(string fileName, string code)
    {
        var path = Path.Combine(_temp.Path, fileName);
        File.WriteAllText(path, code);
        return SourceFile.Read(path)!;
    }

    /// <summary>The file, the program, the check, the line it is said of, the line the change starts on, how many it takes away, and the lines it writes.</summary>
