    [Theory]
    [MemberData(nameof(Searches))]
    public void ASetOfPlacesVisitedNeverAddedToIsFound(string fileName, string code, string check, int line, int changeAt, int removed, string added)
    {
        var found = Assert.Single(LogicPatterns.Scan(Program(fileName, code)), finding => finding.PatternId == check);

        Assert.Equal(line, found.Line);
        Assert.Equal(changeAt, found.Fix!.StartLine);
        Assert.Equal(removed, found.Fix.RemoveCount);
        Assert.Equal(added.Split('|'), found.Fix.NewLines);
    }

    /// <summary>
    /// The searches adding each place; a set filled by a function whose parameter has another name; a set of words asked in a
    /// loop over them, which is no search; a string asked whether it contains a letter, in a function calling itself; a
    /// breadth-first search marking each place it queues; and a set handed to a function from outside the file.
    /// </summary>
    [Theory]
    [InlineData("Dfs.java", "import java.util.HashSet;\nimport java.util.List;\nimport java.util.Set;\n\npublic class Dfs {\n    static List<List<Integer>> graph = List.of(List.of(1), List.of(2), List.of(0, 3), List.of());\n    static Set<Integer> visited = new HashSet<>();\n\n    static int reach(int node) {\n        if (visited.contains(node)) {\n            return 0;\n        } else {\n            visited.add(node);\n            int count = 1;\n            for (int next : graph.get(node)) {\n                count += reach(next);\n            }\n            return count;\n        }\n    }\n\n    public static void main(String[] args) {\n        System.out.println(reach(0));\n    }\n}\n")]
    [InlineData("dfs.py", "graph = {0: [1], 1: [2], 2: [0, 3], 3: []}\n\n\ndef count_reached(start):\n    visited = set()\n\n    def reach(node):\n        if node in visited:\n            return 0\n        else:\n            visited.add(node)\n            return 1 + sum(reach(next_node) for next_node in graph[node])\n\n    return reach(start)\n\n\nprint(count_reached(0))\n")]
    [InlineData("Program.cs", "using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static readonly int[][] Graph = { new[] { 1 }, new[] { 2 }, new[] { 0, 3 }, new int[0] };\n\n    static int Reach(int node, HashSet<int> visited)\n    {\n        if (visited.Contains(node)) return 0;\n        visited.Add(node);\n        int count = 1;\n        foreach (int next in Graph[node]) count += Reach(next, visited);\n        return count;\n    }\n\n    static void Main()\n    {\n        Console.WriteLine(Reach(0, new HashSet<int>()));\n    }\n}\n")]
