    [InlineData("reach.dart", "final graph = [[1], [2], [0, 3], <int>[]];\nfinal visited = <int>{};\n\nint reach(int node) {\n  if (visited.contains(node)) return 0;\n  visited.add(node);\n  var count = 1;\n  for (final next in graph[node]) {\n    count += reach(next);\n  }\n  return count;\n}\n\nvoid main() {\n  print(reach(0));\n}\n")]
