    [InlineData("reach.lua", "local graph = { [0] = { 1 }, [1] = { 2 }, [2] = { 0, 3 }, [3] = {} }\nlocal visited = {}\n\nlocal function reach(node)\n  if visited[node] then\n    return 0\n  end\n  visited[node] = true\n  local count = 1\n  for _, next_node in ipairs(graph[node]) do\n    count = count + reach(next_node)\n  end\n  return count\nend\n\nprint(reach(0))\n")]
