    public void ASearchThatAddsEachPlaceOrNoSearchAtAllIsLeftAlone(string fileName, string code)
    {
        Assert.DoesNotContain(LogicPatterns.Scan(Program(fileName, code)), finding => finding.PatternId.EndsWith("visited-never-added", StringComparison.Ordinal));
    }
}
